import json, re, sys

inp = json.load(open(sys.argv[1]))
D = {d['doc_id']: d['text'] for d in inp['documents']}
SETPOINT = {c['condition_id']: c['temperature_C'] for c in inp['study']['conditions']}
CONDS = [c['condition_id'] for c in inp['study']['conditions']]

# mAU/min slope -> uM/s: dA/min / (eps * l) gives mM/min, mAU = 1e-3 AU, so uM/min = mAU / (6.22 * 0.58); then /60
SLOPE_TO_UMS = 1.0 / (6.22 * 0.58) / 60.0


def pnum(s):
    m = re.match(r'^\s*([\d.]+)(?:×10\^(-?\d+))?\s*$', s)
    return float(m.group(1)) * (10.0 ** int(m.group(2)) if m.group(2) else 1.0)


def conc_uM(s):
    m = re.match(r'^\s*([\d.]+)(?:×10\^(-?\d+))?\s*(uM|mM)\s*$', s)
    v = float(m.group(1)) * (10.0 ** int(m.group(2)) if m.group(2) else 1.0)
    return v * (1000.0 if m.group(3) == 'mM' else 1.0)


W = {}


def add(sid, cond, S, v, src, T=None, note=''):
    assert sid not in W, ('duplicate', sid, src, W[sid]['src'])
    W[sid] = dict(id=sid, cond=cond, S=S, v=v, src=src, T=T, note=note, flag9='')


# ---- D2 Ana Okafor CSV: S nmol/L, rate actually uM/min (her correction) ----
COND_D2 = {'Blue block': 'C1', 'Violet block': 'C2', 'Moss block': 'C7', 'Granite block': 'C3'}
for line in D['D2'].splitlines():
    if not line.startswith('HV-'):
        continue
    f = line.split(',', 8)
    add(f[0], COND_D2[f[3]], float(f[5]) / 1000.0, float(f[6]) / 60.0, 'D2', note=f[8] if len(f) > 8 else '')

# ---- slope blocks (D5 Sofia, D10 Mikael): mAU/min, mixed uM/mM concentrations ----
ROW = re.compile(r'^([A-H]\d{2})\s+(HV-\d{4})\s+(.+?)\s+(-?\d+(?:\.\d+)?)\s+(\d+\.\d+)\s*(.*)$')


def slope_block(text, hdr_cond):
    cond, rows = None, []
    for line in text.splitlines():
        if line.startswith('Plate ') and '| Assay' in line:
            cond = hdr_cond(line)
            continue
        m = ROW.match(line)
        if m and cond:
            rows.append(dict(id=m.group(2), cond=cond, S=conc_uM(m.group(3)), slope=float(m.group(4)),
                             T=float(m.group(5)), flag=m.group(6).strip()))
    return rows


def hdr5(line):
    return re.search(r'Assay: (?:cond(?:ition)? )?(C\d)', line).group(1)


def hdr10(line):
    for key, c in [('315.15 K with MPX-9', 'C7'), ('293.15 K, MPX-9 at 0.025', 'C1'),
                   ('pH 9.00 @ 315.15', 'C6'), ('310.15 K', 'C3')]:
        if key in line:
            return c
    raise ValueError(line)


for r in slope_block(D['D5'], hdr5):
    add(r['id'], r['cond'], r['S'], abs(r['slope']) * SLOPE_TO_UMS, 'D5', T=r['T'], note=r['flag'])
for r in slope_block(D['D10'], hdr10):
    add(r['id'], r['cond'], r['S'], abs(r['slope']) * SLOPE_TO_UMS, 'D10', T=r['T'], note=r['flag'])
# D10 re-read of HV-0827 (lid wiped) replaces first reading
W['HV-0827']['v'] = 31.43 * SLOPE_TO_UMS
W['HV-0827']['note'] = 're-read'

# ---- D6 Yuki Tanabe: decimal commas, S mM, rate nM/s ----
for line in D['D6'].splitlines():
    if not line.startswith('HV-'):
        continue
    f = line.split(';', 7)
    ct = f[3]
    if '37' in ct:
        c = 'C3'
    elif re.search(r'\b0 \S+ MPX', ct):
        c = 'C8'
    elif 'MPX' in ct:
        c = 'C7'
    else:
        raise ValueError(ct)
    add(f[0], c, float(f[5].replace(',', '.')) * 1000.0, float(f[6].replace(',', '.')) / 1000.0, 'D6',
        note=f[7] if len(f) > 7 else '')

# ---- D12 Pavel Sokol summary: [S] mM, rates nM/s ----
cond = None
for line in D['D12'].splitlines():
    if line.startswith('Condition:'):
        if 'pH 5.5, 20' in line:
            cond = 'C5'
        elif 'pH 9.0' in line:
            cond = 'C6'
        elif 'pH 7.0 / 20' in line:
            cond = 'C4'
        else:
            raise ValueError(line)
        continue
    if line.strip().startswith('[S] ='):
        S_mM = pnum(line.split('=', 1)[1].split(':')[0])
        for m in re.finditer(r'r\d\s+([\d.]+(?:×10\^-?\d+)?)\s*\((HV-\d{4})', line):
            add(m.group(2), cond, S_mM * 1000.0, pnum(m.group(1)) / 1000.0, 'D12')

# ---- D14 Kofi Mensah notebook: [S] uM, rates nM/min ----
COND_D14 = [('pH 7.00 @ 293.15 K (no inhibitor)', 'C4'),
            ('pH 5.50 @ 315.15 K (DMSO vehicle, no inhibitor)', 'C8'),
            ('pH 7.00 @ 293.15 K + MPX-9 50', 'C2'),
            ('pH 7.00 @ 293.15 K, MPX-9 at 0.025 mM', 'C1')]
cond = None
for line in D['D14'].splitlines():
    if line.startswith('### Plate'):
        cond = next(c for k, c in COND_D14 if k in line)
        continue
    m = re.match(r'^\|\s*(HV-\d{4})\s*\|\s*([A-H]\d{2})\s*\|\s*([\d.]+)\s*\|\s*([\d.E+]+)\s*\|\s*(.*?)\s*\|\s*$', line)
    if m:
        T = None
        k = re.search(r'logged ([\d.]+) K', m.group(5))
        if k:
            T = float(k.group(1)) - 273.15
        add(m.group(1), cond, float(m.group(3)), float(m.group(4)) / 60000.0, 'D14', T=T, note=m.group(5))

# ---- D15 Nadia Kowalczyk bench log: [S] uM, rates mM/min (her confirmed units) ----
D15 = {
    'C8': [('HV-0796', 6, 0.00110), ('HV-0797', 12, 0.00210), ('HV-0798', 20, 0.00292), ('HV-0799', 40, 0.00479),
           ('HV-0800', 80, 0.00625), ('HV-0801', 120, 0.00749), ('HV-0802', 250, 0.00880), ('HV-0803', 400, 0.00887),
           ('HV-0804', 800, 0.00984), ('HV-0805', 1500, 0.0112)],
    'C2': [('HV-0840', 6, 0.000197), ('HV-0841', 12, 0.000422), ('HV-0842', 20, 0.000641), ('HV-0843', 40, 0.00128),
           ('HV-0844', 80, 0.00244), ('HV-0845', 120, 0.00351), ('HV-0846', 250, 0.00629),
           ('HV-0847', 400, 0.00845),  # re-read (clean) replaces the OVR first read 0.0126
           ('HV-0848', 800, 0.0116), ('HV-0849', 1500, 0.0156)],
    'C4': [('HV-0907', 1500, 0.0199), ('HV-0908', 800, 0.0178), ('HV-0909', 400, 0.0155), ('HV-0910', 250, 0.0120),
           ('HV-0911', 120, 0.00900), ('HV-0912', 80, 0.00660), ('HV-0913', 40, 0.00371), ('HV-0914', 20, 0.00217),
           ('HV-0915', 12, 0.00138), ('HV-0916', 6, 0.000699)],
    'C5': [('HV-0738', 6, 0.000432), ('HV-0739', 12, 0.000808), ('HV-0740', 20, 0.00132), ('HV-0741', 40, 0.00242),
           ('HV-0742', 80, 0.00361), ('HV-0743', 120, 0.00458), ('HV-0744', 250, 0.00640), ('HV-0745', 400, 0.00797),
           ('HV-0746', 800, 0.00863), ('HV-0747', 1500, 0.00964)],
}
for c, rows in D15.items():
    for sid, S, v in rows:
        add(sid, c, float(S), v * 1000.0 / 60.0, 'D15')

# ---- D9 automatic raw export (µM/s): overrides any transcription for the same well ----
R9 = re.compile(r'^\d+\s+[A-H]\d{2}\s+(HV-\d{4})\s+([\d.]+)\s+[\d.]+\s+\d+\s*(\w*)$')
raw9 = {}
for line in D['D9'].splitlines():
    m = R9.match(line.strip())
    if m:
        raw9[m.group(1)] = (float(m.group(2)), m.group(3))
for sid, (rate, flag) in raw9.items():
    w = W[sid]
    print('D9 check %s src=%s S=%g src_v=%.5f raw9=%.5f flag=%s' % (sid, w['src'], w['S'], w['v'], rate, flag))
    w['v'] = rate
    w['flag9'] = flag

# ---- corrections (author-confirmed) ----
for n in range(582, 592):  # Kofi: MPX-9 never added -> matching inhibitor-free condition C4
    W['HV-%04d' % n]['cond'] = 'C4'
W['HV-0587']['T'] = 295.4 - 273.15  # block probe logged 295.4 K
W['HV-0667']['S'] = 1500.0  # Pavel addendum: tubes swapped with HV-0675
W['HV-0675']['S'] = 6.0
W['HV-0905']['T'] = 38.7  # Yuki remark: block read 38.7 C
for sid, w in W.items():
    if w['cond'] == 'C6':
        w['v'] *= 0.5  # Ines: 42 C / pH 9.0 mix was 1:250 not 1:500 -> rescale by 250/500

# ---- exclusions ----
MANUAL = {
    'HV-0547': 'bubble present during read (Sofia correction: plate 2 D06)',
    'HV-0527': 'enzyme added twice (Sofia confirmed Ruth report)',
    'HV-0690': 'bubble present throughout read (Ana moved note to A10)',
    'HV-0633': 'SAT on second-highest [S] well, plate 4 row A (Ana)',
    'HV-0639': 'bubble popped after read began (Mikael operator comment)',
    'HV-0705': 'tip lost while dispensing enzyme (Kofi)',
    'HV-0920': 'bubble present until 5 min after read start (Yuki remark)',
    'HV-0610': 'bubble came up before read finished (Pavel summary note)',
}
excluded = {}
for sid, why in MANUAL.items():
    excluded[sid] = why
for sid, w in W.items():
    if w['flag9'] == 'OVR':
        excluded[sid] = 'OVR (raw export)'
    if w['T'] is not None and abs(w['T'] - SETPOINT[w['cond']]) > 1.0:
        excluded[sid] = 'block temp %.2f C vs setpoint %s' % (w['T'], SETPOINT[w['cond']])
    if w['T'] is None and w['src'] in ('D5', 'D10'):
        raise ValueError(sid)
for sid in excluded:
    assert sid in W, sid


# ---- fitting ----
def mm(S, vmax, km):
    return vmax * S / (km + S)


def sse(pts, vmax, km):
    return sum((v - mm(S, vmax, km)) ** 2 for S, v in pts)


def best_vmax(pts, km):
    num = sum(v * S / (km + S) for S, v in pts)
    den = sum((S / (km + S)) ** 2 for S, v in pts)
    return num / den


def golden(f, a, b, it=300):
    g = (5 ** 0.5 - 1) / 2
    c, d = b - g * (b - a), a + g * (b - a)
    fc, fd = f(c), f(d)
    for _ in range(it):
        if fc < fd:
            b, d, fd = d, c, fc
            c = b - g * (b - a)
            fc = f(c)
        else:
            a, c, fc = c, d, fd
            d = a + g * (b - a)
            fd = f(d)
    return (a + b) / 2


def fit_free(pts):
    f = lambda lk: sse(pts, best_vmax(pts, 10 ** lk), 10 ** lk)
    # coarse scan to make sure the minimum is not at the edge of the bracket
    grid = [(-3 + 0.05 * i) for i in range(0, 161)]
    lk = min(grid, key=f)
    lk = golden(f, lk - 0.06, lk + 0.06)
    km = 10 ** lk
    return best_vmax(pts, km), km


def fit_km(pts, vmax):
    f = lambda lk: sse(pts, vmax, 10 ** lk)
    grid = [(-3 + 0.05 * i) for i in range(0, 161)]
    lk = min(grid, key=f)
    lk = golden(f, lk - 0.06, lk + 0.06)
    return 10 ** lk


pts_by = {c: [] for c in CONDS}
ids_by = {c: [] for c in CONDS}
for sid, w in sorted(W.items()):
    if sid in excluded:
        continue
    pts_by[w['cond']].append((w['S'], w['v']))
    ids_by[w['cond']].append(sid)

fitted = {}
for c in CONDS:
    pts = pts_by[c]
    print(c, 'n=%d' % len(pts))
inhib_ref = {'C1': 'C4', 'C2': 'C4', 'C7': 'C8'}
for c in ['C3', 'C4', 'C5', 'C6', 'C8']:
    fitted[c] = fit_free(pts_by[c])
for c in ['C1', 'C2', 'C7']:
    vmax = fitted[inhib_ref[c]][0]
    fitted[c] = (vmax, fit_km(pts_by[c], vmax))

out = {'conditions': [{'condition_id': c, 'vmax': round(fitted[c][0], 6), 'km': round(fitted[c][1], 4)} for c in CONDS],
       'excluded_samples': sorted(excluded)}
for c in CONDS:
    print(c, 'Vmax=%.5f Km=%.3f' % fitted[c], 'n=%d' % len(pts_by[c]))
print('excluded (%d):' % len(excluded))
for sid in sorted(excluded):
    print('  ', sid, W[sid]['cond'], excluded[sid])
print(json.dumps(out, indent=1))
if len(sys.argv) > 2:
    json.dump(out, open(sys.argv[2], 'w'), indent=1)
    print('wrote', sys.argv[2])

